// Build docs/paper/methods.docx from docs/paper/paper-content.json (generated by the backend).
// Display equations are converted from their LaTeX source into native Word equation objects (OMML) by
// latex_to_omml.cjs; the matching PDF is compiled from methods.tex (same content blocks) with xelatex.
//   node docs/paper/tools/build_docx.cjs
const fs = require("fs");
const path = require("path");
const {
  AlignmentType, BorderStyle, Document, HeadingLevel, LevelFormat, Packer, Paragraph, ShadingType, Table, TableCell,
  TableRow, TextRun, WidthType, Footer, PageNumber, Math: OMath, TabStopType,
} = require("docx");
const { latexToMath } = require("./latex_to_omml.cjs");

const root = path.resolve(__dirname, "..");
const blocks = JSON.parse(fs.readFileSync(path.join(root, "paper-content.json"), "utf8"));
const data = JSON.parse(fs.readFileSync(path.join(root, "paper-data.json"), "utf8"));
const BODY = "Calibri";
const MATH = "Cambria Math";
const PAGE_W = 11906, MARGIN = 1134, CONTENT_W = PAGE_W - 2 * MARGIN; // A4, 2 cm margins

const SYMBOLS = { "\\tau": "τ", "\\delta": "δ", "\\theta": "θ", "\\rho": "ρ", "\\ge": "≥", "\\le": "≤", "\\times": "×", "\\cdot": "·", "\\,": " ", "\\ln": "ln" };

/** Convert a small LaTeX subset ($...$ in the generated text) into runs with sub/superscripts. */
function mathRuns(src) {
  let s = src.replace(/\\mathrm\{([^}]*)\}/g, "$1");
  for (const [k, v] of Object.entries(SYMBOLS)) s = s.split(k).join(v);
  const runs = [];
  let i = 0, buf = "";
  const flush = () => { if (buf) runs.push(new TextRun({ text: buf, font: MATH, italics: true })); buf = ""; };
  while (i < s.length) {
    const c = s[i];
    if (c === "_" || c === "^") {
      flush();
      let arg;
      if (s[i + 1] === "{") {
        let depth = 1, j = i + 2;
        while (j < s.length && depth) { if (s[j] === "{") depth++; else if (s[j] === "}") depth--; j++; }
        arg = s.slice(i + 2, j - 1); i = j;
      } else { arg = s[i + 1]; i += 2; }
      runs.push(new TextRun({ text: arg.replace(/[{}]/g, ""), font: MATH, italics: true, subScript: c === "_", superScript: c === "^" }));
    } else if (c === "{" || c === "}" || c === "\\") { i++; }
    else { buf += c; i++; }
  }
  flush();
  return runs;
}

function richRuns(text, opts = {}) {
  const parts = text.split(/(\$[^$]+\$)/g).filter(Boolean);
  return parts.flatMap((p) => (p.startsWith("$") ? mathRuns(p.slice(1, -1)) : [new TextRun({ text: p, font: BODY, ...opts })]));
}

const border = { style: BorderStyle.SINGLE, size: 4, color: "8C8C8C" };
const borders = { top: border, bottom: border, left: border, right: border };

function table(b) {
  const n = b.header.length;
  const first = b.header[0] === "Feature" ? 1800 : 2200;
  const fixed = n > 4 ? [1500, 1650, 1650] : [first];
  const rest = Math.floor((CONTENT_W - fixed.reduce((a, c) => a + c, 0)) / (n - fixed.length));
  const widths = [...fixed, ...Array(n - fixed.length).fill(rest)];
  widths[n - 1] = CONTENT_W - widths.slice(0, n - 1).reduce((a, c) => a + c, 0);
  const cell = (text, w, header) => new TableCell({
    borders, width: { size: w, type: WidthType.DXA }, margins: { top: 60, bottom: 60, left: 90, right: 90 },
    shading: header ? { fill: "E8E4DA", type: ShadingType.CLEAR, color: "auto" } : undefined,
    children: [new Paragraph({ children: richRuns(String(text), { size: 17, bold: header }) })],
  });
  return [
    new Paragraph({ spacing: { before: 160, after: 80 }, keepNext: true, children: [new TextRun({ text: b.caption, font: BODY, italics: true, size: 19 })] }),
    new Table({ width: { size: CONTENT_W, type: WidthType.DXA }, columnWidths: widths,
      rows: [new TableRow({ tableHeader: true, children: b.header.map((h, i) => cell(h, widths[i], true)) }),
        ...b.rows.map((r) => new TableRow({ children: r.map((c, i) => cell(c, widths[i], false)) }))] }),
    new Paragraph({ spacing: { after: 120 }, children: [] }),
  ];
}

const children = [];
for (const b of blocks) {
  if (b.type === "h1") children.push(new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun({ text: b.text })] }));
  else if (b.type === "h2") children.push(new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun({ text: b.text })] }));
  else if (b.type === "p") children.push(new Paragraph({ spacing: { after: 140, line: 288 }, alignment: AlignmentType.JUSTIFIED, children: richRuns(b.text, { size: 22 }) }));
  else if (b.type === "eq") children.push(new Paragraph({ spacing: { before: 120, after: 160 }, tabStops: [{ type: TabStopType.CENTER, position: Math.round(CONTENT_W / 2) }, { type: TabStopType.RIGHT, position: CONTENT_W }],
    children: [new TextRun({ text: "	" }), new OMath({ children: latexToMath(b.latex) }), new TextRun({ text: `	(${b.n})`, font: BODY, size: 22 })] }));
  else if (b.type === "table") children.push(...table(b));
  else if (b.type === "list") for (const item of b.items) children.push(new Paragraph({ numbering: { reference: "bullets", level: 0 }, spacing: { after: 80, line: 276 }, children: richRuns(item, { size: 21 }) }));
}

const doc = new Document({
  creator: "AlterEcho (Team AlterEcho)", title: "Methods: Earth–Planetary Terrain Analogue Comparison",
  description: `Generated from ${data.method_version} / ${data.terrain_method}`,
  styles: {
    default: { document: { run: { font: BODY, size: 22 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true, run: { font: "Cambria", size: 32, bold: true, color: "1F2A36" }, paragraph: { spacing: { before: 320, after: 160 }, keepNext: true, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true, run: { font: "Cambria", size: 25, bold: true, color: "2E3B4A" }, paragraph: { spacing: { before: 240, after: 100 }, keepNext: true, outlineLevel: 1 } },
    ],
  },
  numbering: { config: [{ reference: "bullets", levels: [{ level: 0, format: LevelFormat.BULLET, text: "•", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 540, hanging: 270 } } } }] }] },
  sections: [{
    properties: { page: { size: { width: PAGE_W, height: 16838 }, margin: { top: MARGIN, bottom: MARGIN, left: MARGIN, right: MARGIN } } },
    footers: { default: new Footer({ children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: `AlterEcho · ${data.method_version} · page `, size: 16, color: "777777" }), new TextRun({ children: [PageNumber.CURRENT], size: 16, color: "777777" })] })] }) },
    children,
  }],
});

Packer.toBuffer(doc).then((buf) => {
  const out = path.join(root, "methods.docx");
  fs.writeFileSync(out, buf);
  console.log("wrote", out, "with", blocks.filter((b) => b.type === "eq").length, "native equations");
});
